          "correctAnswer": 3,
          "explanation": "<b>Dịch nghĩa:</b> Việc ngáp một cái thật to trước mặt người khác là một hành động rất khó coi, đáng xấu hổ.<br><b>Từ vựng đồng nghĩa:</b> 「みっともない」 nghĩa là xấu xí, khó coi, đáng hổ thẹn về mặt thể diện tác phong, đồng nghĩa với 「恥ずかしい」（はずかしい）.<br><i>Phân tích các phương án:</i><br>• 1. 危険だ: Nguy hiểm.<br>• 2. 無駄だ: Lãng phí, vô ích.<br>• 3. <b>恥ずかしい: [Đúng]</b> Đáng xấu hổ, khó coi (đồng nghĩa với みっともない).<br>• 4. 面倒だ: Phiền phức, rắc rối."
